        class: 'map-preview__meta',
        text: `${cluster.members.length > titles.length ? '… ' : ''}Klicken vergrössert die Ansicht.`,
      }),
    ]),
  );
  placePreview(marker, 320);
  for (const [, node] of clusters) node.element.classList.toggle('is-preview', node === cluster);
}

