#!/usr/bin/env node
// Phone probe: does the “Karten an diesem Punkt” list stay usable at 390/320 px?
import { spawn } from 'node:child_process';
import { mkdtemp, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const WIDTH = Number(process.argv[2] ?? 390);
const HEIGHT = Number(process.argv[3] ?? 844);
const PORT = 9413 + (WIDTH === 320 ? 1 : 0);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-phone-'));
const child = spawn('/usr/bin/chromium', [
  '--headless=new', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`,
  '--no-sandbox', '--disable-gpu', '--hide-scrollbars', `--window-size=${WIDTH},${HEIGHT}`, 'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) {
  for (let i = 0; i < 60; i++) {
    try { const res = await fetch(`http://127.0.0.1:${PORT}${p}`); if (res.ok) return res.json(); } catch {}
    await sleep(200);
  }
  throw new Error(`no CDP at ${p}`);
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
const errors = [];
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.exception?.description);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
};
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const msgId = ++id;
  pending.set(msgId, (msg) => (msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result)));
  ws.send(JSON.stringify({ id: msgId, method, params }));
});
const evaluate = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? 'eval failed');
  return r.result.value;
};

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: WIDTH, height: HEIGHT, deviceScaleFactor: 2, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });

const pile = await evaluate(`(async () => {
  const seed = await (await fetch('/data/records.json')).json();
  const records = seed.records ?? seed;
  const groups = new Map();
  for (const record of records) {
    if (!record.geo) continue;
    const key = record.geo.lat.toFixed(6) + ':' + record.geo.lon.toFixed(6);
    groups.set(key, [...(groups.get(key) ?? []), record]);
  }
  const biggest = [...groups.values()].filter((l) => l.length > 2).sort((a, b) => b.length - a.length)[0];
  const years = biggest.map((r) => r.yearStart).sort((a, b) => a - b);
  return { count: biggest.length, lat: biggest[0].geo.lat, lon: biggest[0].geo.lon, from: years[0], to: years[years.length - 1] };
})()`);
await send('Page.navigate', { url: `http://127.0.0.1:8787/?lat=${pile.lat}&lon=${pile.lon}&z=17&from=${pile.from}&to=${pile.to}` });
await sleep(5000);
await evaluate(`(async () => { for (let i = 0; i < 80; i++) { if (document.querySelector('.map-cluster[data-action="list"]')) return true; await new Promise((r) => setTimeout(r, 250)); } return false; })()`);
await evaluate(`document.querySelector('.map-cluster[data-action="list"]').click()`);
await sleep(800);
const state = await evaluate(`(() => {
  const list = document.querySelector('.map-cluster-list');
  const items = [...list.querySelectorAll('.map-cluster-list__item')];
  const rect = list.getBoundingClientRect();
  const mapRect = document.querySelector('#map').getBoundingClientRect();
  return {
    viewport: [innerWidth, innerHeight],
    hidden: list.hidden,
    items: items.length,
    rect: { x: Math.round(rect.x), y: Math.round(rect.y), w: Math.round(rect.width), h: Math.round(rect.height) },
    insideMap: rect.left >= mapRect.left - 1 && rect.right <= mapRect.right + 1 && rect.top >= mapRect.top - 1 && rect.bottom <= mapRect.bottom + 1,
    rowHeights: items.map((i) => Math.round(i.getBoundingClientRect().height)),
    minRowHeight: Math.min(...items.map((i) => i.getBoundingClientRect().height)),
    clippedText: items.filter((i) => i.scrollWidth > i.clientWidth + 1).length,
    overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    closeSize: (() => { const r = list.querySelector('.map-cluster-list__close').getBoundingClientRect(); return [Math.round(r.width), Math.round(r.height)]; })(),
    footInView: (() => { const b = list.querySelector('.map-cluster-list__foot');
      if (!b) return null; return b.getBoundingClientRect().bottom <= list.getBoundingClientRect().bottom + 1; })(),
    scrollable: list.scrollHeight > list.clientHeight,
    listScrolls: getComputedStyle(list).overflowY,
  };
})()`);
console.log(`PHONE ${WIDTH}x${HEIGHT}`, JSON.stringify(state, null, 2));
const shot = await send('Page.captureScreenshot', { format: 'png' });
await writeFile(`/tmp/phone-pile-${WIDTH}.png`, Buffer.from(shot.data, 'base64'));
console.log('ERRORS', errors.length, errors.slice(0, 3));
ws.close();
child.kill('SIGKILL');

